class Solution {
public:
    int longestLine(vector<vector<int>>& mat) {
        if (mat.empty() || mat[0].empty()) {
            return 0;
        }
        int m = mat.size(), n = mat[0].size(), answer = 0;
        vector<array<int, 4>> previous(n), current(n);
        for (int r = 0; r < m; ++r) {
            fill(current.begin(), current.end(), array<int, 4>{{0, 0, 0, 0}});
            for (int c = 0; c < n; ++c) {
                if (mat[r][c] == 0) {
                    continue;
                }
                current[c][0] = (c ? current[c - 1][0] : 0) + 1;
                current[c][1] = previous[c][1] + 1;
                current[c][2] = (c ? previous[c - 1][2] : 0) + 1;
                current[c][3] = (c + 1 < n ? previous[c + 1][3] : 0) + 1;
                for (int length : current[c]) {
                    answer = max(answer, length);
                }
            }
            previous.swap(current);
        }
        return answer;
    }
};
